import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ProgramMetric {
  id: string;
  name: string;
  peopleServed: number;
  totalCost: number;
  costPerPerson: number; // ROI metric
  month: string;
}

export interface DashboardStats {
  totalPeopleServed: number;
  totalBudgetSpent: number;
  avgCostPerPerson: number;
  programs: ProgramMetric[];
}

export interface GeneratedReport {
  title: string;
  content: string; // Markdown content
  generatedAt: string;
}

import { GoogleGenAI } from "@google/genai";
import { DashboardStats } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateImpactReport = async (data: DashboardStats): Promise<string> => {
  try {
    const prompt = `
      You are an expert nonprofit analyst for "Nomad Compass". 
      Analyze the following dashboard data and generate a concise, professional Executive Impact Report in Markdown format.

      Data:
      ${JSON.stringify(data, null, 2)}

      Structure the report with these sections:
      1. **Executive Summary**: A brief overview of total impact.
      2. **Efficiency Analysis**: Comment on the Cost per Person (ROI). Is it sustainable?
      3. **Program Highlights**: Mention specific trends based on the monthly data provided.
      4. **Recommendations**: 2-3 actionable steps to improve impact or reduce costs.

      Keep the tone inspiring but data-driven.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Unable to generate report at this time.";
  } catch (error) {
    console.error("Error generating report:", error);
    throw new Error("Failed to generate impact report.");
  }
};

import React from 'react';
import { ArrowUpRight, ArrowDownRight, HelpCircle } from 'lucide-react';

interface StatCardProps {
  title: string;
  value: string;
  trend?: string;
  trendDirection?: 'up' | 'down' | 'neutral';
  icon: React.ReactNode;
  description?: string;
  colorClass: string;
}

export const StatCard: React.FC<StatCardProps> = ({ 
  title, 
  value, 
  trend, 
  trendDirection = 'neutral', 
  icon, 
  description,
  colorClass 
}) => {
  return (
    <div className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 hover:shadow-md transition-shadow duration-200">
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-lg ${colorClass} bg-opacity-10`}>
          {icon}
        </div>
        {trend && (
          <div className={`flex items-center text-xs font-medium px-2 py-1 rounded-full ${
            trendDirection === 'up' ? 'bg-green-50 text-green-700' : 
            trendDirection === 'down' ? 'bg-red-50 text-red-700' : 'bg-slate-100 text-slate-600'
          }`}>
            {trendDirection === 'up' ? <ArrowUpRight className="w-3 h-3 mr-1" /> : <ArrowDownRight className="w-3 h-3 mr-1" />}
            {trend}
          </div>
        )}
      </div>
      <div>
        <h3 className="text-slate-500 text-sm font-medium uppercase tracking-wide mb-1">{title}</h3>
        <div className="text-3xl font-bold text-slate-900">{value}</div>
        {description && (
          <p className="text-slate-400 text-xs mt-2 flex items-center">
             {description}
          </p>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { X, Download, Copy, FileText } from 'lucide-react';

interface ImpactReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  reportContent: string;
  isLoading: boolean;
}

export const ImpactReportModal: React.FC<ImpactReportModalProps> = ({ isOpen, onClose, reportContent, isLoading }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-brand-100 rounded-lg text-brand-700">
              <FileText size={20} />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-800">Nomad Compass Impact Report</h2>
              <p className="text-xs text-slate-500">Generated by Gemini AI</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-8 prose-content">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-64 space-y-4">
              <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin"></div>
              <p className="text-slate-500 font-medium animate-pulse">Analyzing program data...</p>
            </div>
          ) : (
            <div className="prose prose-slate prose-sm max-w-none">
              <div className="whitespace-pre-wrap text-slate-700 leading-relaxed font-normal">
                {reportContent.split('\n').map((line, i) => {
                  if (line.startsWith('# ')) return <h1 key={i} className="text-2xl font-bold mb-4 text-slate-900">{line.replace('# ', '')}</h1>
                  if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-semibold mt-6 mb-3 text-slate-800">{line.replace('## ', '')}</h2>
                  if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-medium mt-4 mb-2 text-slate-800">{line.replace('### ', '')}</h3>
                  if (line.startsWith('- ') || line.startsWith('* ')) return <li key={i} className="ml-4 list-disc marker:text-brand-500 mb-1">{line.replace(/[-*] /, '')}</li>
                  if (line.match(/^\d\./)) return <li key={i} className="ml-4 list-decimal marker:text-slate-400 mb-1">{line.substring(line.indexOf(' ') + 1)}</li>
                  if (line.trim() === '') return <br key={i} />
                  // Bold text parsing simple
                  const parts = line.split('**');
                  if(parts.length > 1) {
                      return <p key={i} className="mb-2">
                          {parts.map((part, index) => index % 2 === 1 ? <strong key={index} className="text-slate-900 font-semibold">{part}</strong> : part)}
                      </p>
                  }
                  return <p key={i} className="mb-2">{line}</p>
                })}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 flex justify-end gap-3 bg-slate-50">
          <button className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-900 transition-colors">
            <Copy size={16} />
            Copy Text
          </button>
          <button className="flex items-center gap-2 px-4 py-2 bg-brand-600 text-white rounded-lg hover:bg-brand-700 transition-colors shadow-sm text-sm font-medium">
            <Download size={16} />
            Export PDF
          </button>
        </div>
      </div>
    </div>
  );
};

