import { GoogleGenAI } from "@google/genai";
import { DashboardStats } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateImpactReport = async (data: DashboardStats): Promise<string> => {
  try {
    const prompt = `
      You are a grantmaking expert and senior nonprofit analyst for "Nomad Compass". 
      Analyze the following comprehensive dashboard data and generate a detailed, grant-ready Impact Report in Markdown format.

      Data:
      ${JSON.stringify(data, null, 2)}

      Structure the report with these sections:
      1. **Executive Summary**: A powerful overview of the total impact and theory of change.
      2. **Outcomes & Effectiveness**: Analyze the specific outcomes (Water Access, Health, Behavior) and the SROI ($${data.sroi}). Compare cost effectiveness to the benchmark (${data.benchmarkComparison}).
      3. **Equity & Reach**: Discuss the demographics served (Age, Race, Disability) and geographic focus (Neighborhoods, Urban/Rural split).
      4. **Financial Health & Sustainability**: Analyze the spending breakdown (Program vs Admin) and funding diversity. Mention the operating reserves.
      5. **Data Quality Statement**: Confirm the data quality level (${data.dataQuality.level}) and evaluation method.
      6. **Strategic Recommendations**: 3 actionable steps to scale impact or improve efficiency.

      Tone: Professional, evidence-based, persuasive, and suitable for submission to major foundations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Unable to generate report at this time.";
  } catch (error) {
    console.error("Error generating report:", error);
    throw new Error("Failed to generate impact report.");
  }
};

