import { GoogleGenAI, SchemaType } from "@google/genai";
import { DashboardStats, AIAnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateDashboardInsights = async (data: DashboardStats): Promise<AIAnalysisData> => {
  try {
    const prompt = `
      Analyze the following nonprofit dashboard data for "Nomad Compass". 
      Provide strategic insights, risks, and recommendations.

      Data:
      ${JSON.stringify(data)}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: SchemaType.OBJECT,
          properties: {
            keyFindings: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
            recommendations: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
            risks: { type: SchemaType.ARRAY, items: { type: SchemaType.STRING } },
            trendAnalysis: { type: SchemaType.STRING },
            readinessScore: { type: SchemaType.INTEGER, description: "Grant readiness score between 0 and 100" }
          },
          required: ["keyFindings", "recommendations", "risks", "trendAnalysis", "readinessScore"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned");

    return JSON.parse(text) as AIAnalysisData;
  } catch (error) {
    console.error("Error generating insights:", error);
    // Return fallback data if AI fails
    return {
      keyFindings: ["Data analysis unavailable at this moment.", "Please check connection."],
      recommendations: ["Review manual reports."],
      risks: ["Analysis incomplete."],
      trendAnalysis: "Unable to calculate.",
      readinessScore: 0
    };
  }
};

export const generateImpactReport = async (data: DashboardStats): Promise<string> => {
  try {
    const prompt = `
      You are a grantmaking expert and senior nonprofit analyst for "Nomad Compass". 
      Analyze the following comprehensive dashboard data and generate a detailed, grant-ready Impact Report in Markdown format.

      Data:
      ${JSON.stringify(data, null, 2)}

      Structure the report with these sections:
      1. **Executive Summary**: A powerful overview (3-4 paragraphs) of the total impact and theory of change.
      2. **Grant Readiness Score**: Assess the organization's readiness (0-100) based on data quality, financial health, and outcomes. Explain the score.
      3. **Strengths & Weaknesses Analysis**: specific bullet points.
      4. **Outcomes & Effectiveness**: Analyze the specific outcomes (Water Access, Health, Behavior) and the SROI ($${data.sroi}). Compare cost effectiveness to the benchmark (${data.benchmarkComparison}).
      5. **Equity & Reach**: Discuss the demographics served (Age, Race, Disability) and geographic focus (Neighborhoods, Urban/Rural split).
      6. **Financial Health & Sustainability**: Analyze the spending breakdown (Program vs Admin) and funding diversity. Mention the operating reserves.
      7. **Strategic Recommendations**: 3 actionable steps to scale impact or improve efficiency.
      8. **Comparable Organization Analysis**: Compare these metrics to typical similar nonprofits in the sector.

      Tone: Professional, evidence-based, persuasive, and suitable for submission to major foundations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Unable to generate report at this time.";
  } catch (error) {
    console.error("Error generating report:", error);
    throw new Error("Failed to generate impact report.");
  }
};

