import { GoogleGenAI, Type } from "@google/genai";
import { DashboardStats, AIAnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateDashboardInsights = async (data: DashboardStats): Promise<AIAnalysisData> => {
  try {
    const prompt = `
      Analyze the following nonprofit dashboard data for "Nomad Compass". 
      Provide strategic insights, risks, and recommendations.

      Data:
      ${JSON.stringify(data)}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            keyFindings: { type: Type.ARRAY, items: { type: Type.STRING } },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
            risks: { type: Type.ARRAY, items: { type: Type.STRING } },
            trendAnalysis: { type: Type.STRING },
            readinessScore: { type: Type.INTEGER, description: "Grant readiness score between 0 and 100" }
          },
          required: ["keyFindings", "recommendations", "risks", "trendAnalysis", "readinessScore"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned");

    return JSON.parse(text) as AIAnalysisData;
  } catch (error) {
    console.error("Error generating insights:", error);
    // Return fallback data if AI fails
    return {
      keyFindings: ["Data analysis unavailable at this moment.", "Please check connection."],
      recommendations: ["Review manual reports."],
      risks: ["Analysis incomplete."],
      trendAnalysis: "Unable to calculate.",
      readinessScore: 0
    };
  }
};

export const generateImpactReport = async (data: DashboardStats): Promise<string> => {
  try {
    const prompt = `
      You are a grantmaking expert and senior nonprofit analyst for "Nomad Compass". 
      Analyze the following comprehensive dashboard data and generate a detailed, grant-ready Impact Report in Markdown format.

      Data:
      ${JSON.stringify(data, null, 2)}

      Structure the report with these sections:
      1. **Executive Summary**: A powerful overview (3-4 paragraphs) of the total impact and theory of change.
      2. **Grant Readiness Score**: Assess the organization's readiness (0-100) based on data quality, financial health, and outcomes. Explain the score.
      3. **Strengths & Weaknesses Analysis**: specific bullet points.
      4. **Outcomes & Effectiveness**: Analyze the specific outcomes (Water Access, Health, Behavior) and the SROI ($${data.sroi}). Compare cost effectiveness to the benchmark (${data.benchmarkComparison}).
      5. **Equity & Reach**: Discuss the demographics served (Age, Race, Disability) and geographic focus (Neighborhoods, Urban/Rural split).
      6. **Financial Health & Sustainability**: Analyze the spending breakdown (Program vs Admin) and funding diversity. Mention the operating reserves.
      7. **Strategic Recommendations**: 3 actionable steps to scale impact or improve efficiency.
      8. **Comparable Organization Analysis**: Compare these metrics to typical similar nonprofits in the sector.

      Tone: Professional, evidence-based, persuasive, and suitable for submission to major foundations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Unable to generate report at this time.";
  } catch (error) {
    console.error("Error generating report:", error);
    throw new Error("Failed to generate impact report.");
  }
};

import React from 'react';
import { ArrowUpRight, ArrowDownRight, Activity } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area } from 'recharts';

interface StatCardProps {
  title: string;
  value: string;
  trend?: string;
  trendDirection?: 'up' | 'down' | 'neutral';
  icon: React.ReactNode;
  description?: string;
  gradientFrom: string;
  gradientTo: string;
  sparklineData?: { value: number }[];
  subValue?: string;
}

export const StatCard: React.FC<StatCardProps> = ({ 
  title, 
  value, 
  trend, 
  trendDirection = 'neutral', 
  icon, 
  description,
  gradientFrom,
  gradientTo,
  sparklineData,
  subValue
}) => {
  return (
    <div className={`relative overflow-hidden rounded-2xl p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-xl group bg-gradient-to-br ${gradientFrom} ${gradientTo}`}>

      {/* Background decoration */}
      <div className="absolute -right-6 -top-6 w-32 h-32 bg-white opacity-10 rounded-full blur-2xl group-hover:opacity-20 transition-opacity duration-500"></div>

      <div className="relative z-10 text-white">
        <div className="flex justify-between items-start mb-2">
          <div className="p-2 rounded-xl bg-white/20 backdrop-blur-sm shadow-inner">
            {React.cloneElement(icon as React.ReactElement<any>, { className: 'text-white w-5 h-5' })}
          </div>

          {trend && (
            <div className={`flex items-center text-xs font-bold px-2 py-1 rounded-full backdrop-blur-md bg-white/20 border border-white/10 shadow-sm`}>
              {trendDirection === 'up' ? <ArrowUpRight className="w-3 h-3 mr-1" /> : <ArrowDownRight className="w-3 h-3 mr-1" />}
              {trend}
            </div>
          )}
        </div>

        <h3 className="text-white/80 text-sm font-medium uppercase tracking-wider mb-1 mt-4">{title}</h3>
        <div className="flex items-baseline gap-2">
          <div className="text-3xl font-bold tracking-tight drop-shadow-sm">{value}</div>
          {subValue && <span className="text-sm font-medium text-white/70">{subValue}</span>}
        </div>

        {description && (
          <p className="text-white/70 text-xs mt-1 flex items-center font-light">
             {description}
          </p>
        )}
      </div>

      {/* Sparkline Chart */}
      {sparklineData && (
        <div className="absolute bottom-0 left-0 right-0 h-16 opacity-30 group-hover:opacity-50 transition-opacity">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={sparklineData}>
              <Area 
                type="monotone" 
                dataKey="value" 
                stroke="#fff" 
                fill="#fff" 
                strokeWidth={2}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
};
